:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c5ce7;
  --accent: #00cec9;
  --text: #f0f0f0;
  --card-back: #3d3d5c;
  --card-border: #5a5a7a;
  --matched: #00b894;
  --focus: #fdcb6e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: 16px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.game-header {
  text-align: center;
  width: 100%;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--accent);
}

.stats {
  font-size: 1.1rem;
  display: flex;
  justify-content: center;
  gap: 8px;
}

.stat-label {
  color: #a0a0b8;
}

.stat-value {
  font-weight: 700;
  color: var(--accent);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  width: 100%;
  max-width: 400px;
}

.card {
  aspect-ratio: 1;
  background: var(--card-back);
  border: 2px solid var(--card-border);
  border-radius: 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: transparent;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  user-select: none;
  position: relative;
  padding: 0;
  min-width: 0;
}

.card:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.card:hover:not(.matched):not(.flipped) {
  background: #4a4a6a;
  border-color: var(--primary);
}

.card:active:not(.matched):not(.flipped) {
  transform: scale(0.95);
}

.card.flipped,
.card.matched {
  background: var(--primary);
  border-color: var(--accent);
  color: var(--text);
}

.card.matched {
  background: var(--matched);
  border-color: var(--matched);
  cursor: default;
}

.card .symbol {
  opacity: 0;
  transition: opacity 0.2s;
}

.card.flipped .symbol,
.card.matched .symbol {
  opacity: 1;
}

.win-message {
  background: var(--matched);
  color: #fff;
  padding: 16px 24px;
  border-radius: 12px;
  text-align: center;
  font-size: 1.25rem;
  font-weight: 600;
  width: 100%;
  animation: pop 0.3s ease;
}

@keyframes pop {
  0% { transform: scale(0.9); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

.new-game-btn {
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: 10px;
  padding: 14px 32px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  width: 100%;
  max-width: 300px;
}

.new-game-btn:hover {
  background: #5a4bd1;
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.new-game-btn:active {
  transform: scale(0.97);
  background: #4a3bc1;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .game-board {
    gap: 6px;
  }
  .card {
    font-size: 1.2rem;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
    '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
  ];

  const board = document.getElementById('game-board');
  const moveCounter = document.getElementById('move-counter');
  const winMessage = document.getElementById('win-message');
  const finalMoves = document.getElementById('final-moves');
  const newGameBtn = document.getElementById('new-game-btn');

  let deck = [];
  let flipped = [];
  let moves = 0;
  let matchedPairs = 0;
  let lockBoard = false;

  function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  function createDeck() {
    const cards = [];
    COLORS.forEach((color, index) => {
      cards.push({ id: index, color });
      cards.push({ id: index, color });
    });
    return shuffle(cards);
  }

  function renderBoard() {
    board.innerHTML = '';
    deck.forEach((card, i) => {
      const btn = document.createElement('button');
      btn.className = 'card';
      btn.type = 'button';
      btn.dataset.index = i;
      btn.dataset.pairId = card.id;
      btn.setAttribute('aria-label', 'Card ' + (i + 1) + ', face down');
      btn.innerHTML = '<span class="symbol" style="color:' + card.color + '">●</span>';
      btn.addEventListener('click', handleCardClick);
      board.appendChild(btn);
    });
  }

  function handleCardClick(e) {
    const card = e.currentTarget;
    if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) {
      return;
    }

    card.classList.add('flipped');
    card.setAttribute('aria-label', 'Card ' + (parseInt(card.dataset.index) + 1) + ', face up');
    flipped.push(card);

    if (flipped.length === 2) {
      moves++;
      moveCounter.textContent = moves;
      checkMatch();
    }
  }

  function checkMatch() {
    const [a, b] = flipped;
    if (a.dataset.pairId === b.dataset.pairId) {
      a.classList.add('matched');
      b.classList.add('matched');
      a.disabled = true;
      b.disabled = true;
      a.setAttribute('aria-label', 'Matched card');
      b.setAttribute('aria-label', 'Matched card');
      matchedPairs++;
      flipped = [];
      if (matchedPairs === COLORS.length) {
        winGame();
      }
    } else {
      lockBoard = true;
      setTimeout(() => {
        a.classList.remove('flipped');
        b.classList.remove('flipped');
        a.setAttribute('aria-label', 'Card ' + (parseInt(a.dataset.index) + 1) + ', face down');
        b.setAttribute('aria-label', 'Card ' + (parseInt(b.dataset.index) + 1) + ', face down');
        flipped = [];
        lockBoard = false;
      }, 800);
    }
  }

  function winGame() {
    finalMoves.textContent = moves;
    winMessage.hidden = false;
    newGameBtn.focus();
  }

  function resetGame() {
    deck = createDeck();
    flipped = [];
    moves = 0;
    matchedPairs = 0;
    lockBoard = false;
    moveCounter.textContent = '0';
    winMessage.hidden = true;
    renderBoard();
    const firstCard = board.querySelector('.card');
    if (firstCard) firstCard.focus();
  }

  newGameBtn.addEventListener('click', resetGame);

  resetGame();
})();
